/// <summary>
/// MPJ-21310 Entry point for processes that need to check substitutes
/// for sales order lines at point of reservation.
/// </summary>
class METSalesItemSubstitutionApplyAtReservation
{

}

Method.Source:
/// <summary>Check for substitutes, to be used at point of reservation/release to warehouse.
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <returns>Validation result.</returns>
public static boolean checkAndUpdateLine(SalesLine _salesLine)
{
    // TODO this needs to receive back the copied sales line if one exists.
    METSalesItemSubstitution sub = METSalesItemSubstitution::construct(
        _salesLine,
        _salesLine.metSalesLine(true),
        _salesLine.inventDim(), 
        METSalesItemSubstitutionEventSource::Reservation,            
        false);
    return sub.run();
}

    /// <summary>
    /// Check substitutes for all lines on specified order.
    /// </summary>
    /// <param name = "_salesID">_salesID</param>
    /// <returns>Validation result</returns>
    public static boolean checkAndUpdateOrder(SalesId _salesID)
    {
        boolean     ret = true;
        SalesLine   salesLine;

        ttsbegin;
        while select forupdate salesLine
            where   salesLine.SalesId   == _salesID
        {
            ret = METSalesItemSubstitutionApplyAtReservation::checkAndUpdateLine(salesLine) && ret;
        }
        ttscommit;
        return ret;
    }

public static void main(Args _args)
{
    SalesLine salesLine = _args.record();
    if(!salesLine)
    {
        throw error(error::missingRecord(funcName()));
    }
    if(!METSalesItemSubstitutionApplyAtReservation::checkAndUpdateLine(salesLine))
    {
        throw error("@MET:SubValidationFailed");
    }
    if(salesLine.dataSource())
    {
        FormDataUtil::getFormDataSource(salesLine).research(true);
    }
}
